L = 1, S = 2
@pytest.mark.parametrize("L,S", SHAPES) def test_mf1_parity_reference_is_bottom_right(L, S): rng = np.random.default_rng(1000 * L + S) H, D = 2, 16 q = rng.standard_normal((1, H, L, D)).astype(np.float32) k = rng.standard_normal((1, H, S, D)).astype(np.float32) v = rng.standard_normal((1, H, S, D)).astype(np.float32) g = rng.standard_normal((1, H, L, D)).astype(np.float32) out, kq, mask = TP.reference_forward(q, k, v, bulk_bits=2, refine_percentile=P, is_causal=True) gq, gk, gv = TP.reference_backward(g, q, k, v, kq, mask, is_causal=True) scale = D ** -0.5 vis = R.visible_mask(L, S) abs_rank = np.abs(np.einsum("bhld,bhsd->bhls", q.astype(np.float64), k.astype(np.float64)) * scale) sel_ref, thr = R.tgv2_apa_select(abs_rank, vis, S, P, float(norm.ppf(1.0 - P))) amb = R.ambiguous(abs_rank, thr, 1e-5) & vis dis = int((vis & ~amb & (mask != sel_ref)).sum()) sel_use = np.where(amb, mask, sel_ref) ref_out = R.apa_tc_reference(q, k, kq, v, scale, sel_use) ref_g = R.tgv2_apa_backward(q, k, kq, v, g, scale, sel_use) errs = [R.rel_err(out, ref_out)] + [R.rel_err(a, b) for a, b in zip((gq, gk, gv), ref_g)] msg = (f"L={L} S={S} nontie_disagree={dis} ties={int(amb.sum())} " + " ".join(f"{n}:rel={e[0]:.3e},maxabs={e[1]:.3e}" for n, e in zip(("out", "dq", "dk", "dv"), errs))) print(msg) > assert dis == 0 and all(e[0] <= 1e-5 for e in errs), msg E AssertionError: L=1 S=2 nontie_disagree=0 ties=2 out:rel=1.101e+00,maxabs=1.442e+00 dq:rel=1.000e+00,maxabs=3.221e-01 dk:rel=1.000e+00,maxabs=2.688e-01 dv:rel=7.370e-01,maxabs=9.149e-01 E assert (0 == 0 and False) E + where False = all(<generator object test_mf1_parity_reference_is_bottom_right.<locals>.<genexpr> at 0x736c1516d490>)
